arguments.old_string:
def _gen_print(self, node: ast.Call) -> str:
    if len(node.args) == 0:
        return 'printf("\\n")'
    if len(node.args) != 1:
        raise UnsupportedError("print() supports a single argument", node)
    arg = node.args[0]
    t = self._infer(arg)
    expr = self._gen_expr(arg)
    if isinstance(t, IntType):
        return f'printf("%ld\\n", {expr})'
    if isinstance(t, BoolType):
        return f'printf("%s\\n", ({expr}) ? "True" : "False")'
    if isinstance(t, FloatType):
        return f'printf("%g\\n", {expr})'
    if isinstance(t, StrType):
        return f'printf("%s\\n", {expr})'
    raise UnsupportedError(f"cannot print value of type '{t}'", node)

arguments.new_string:
def _gen_print(self, node: ast.Call) -> str:
    if node.keywords:
        raise UnsupportedError(
            "print() keyword arguments not supported", node)
    if len(node.args) == 0:
        return 'printf("\\n")'
    fmts: list[str] = []
    args: list[str] = []
    for arg in node.args:
        t = self._infer(arg)
        expr = self._gen_expr(arg)
        if isinstance(t, IntType):
            fmts.append("%ld")
            args.append(expr)
        elif isinstance(t, BoolType):
            fmts.append("%s")
            args.append(f'(({expr}) ? "True" : "False")')
        elif isinstance(t, FloatType):
            fmts.append("%g")
            args.append(expr)
        elif isinstance(t, StrType):
            fmts.append("%s")
            args.append(expr)
        else:
            raise UnsupportedError(
                f"cannot print value of type '{t}'", arg)
    fmt = " ".join(fmts) + "\\n"
    return f'printf("{fmt}", ' + ", ".join(args) + ")"
